pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _test_setL1BlockValues_changes_hash_only_for_depositor(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hashNew, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) internal {
        bytes32 h0;
        try c.hash() returns (bytes32 __r) { h0 = __r; } catch { return; }
        vm.assume(h0 != _hashNew);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hashNew,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {} catch { return; }
        bytes32 h1;
        try c.hash() returns (bytes32 __r) { h1 = __r; } catch { return; }
        assertTrue(h1 == h0);
    }

    function testFuzz_test_setL1BlockValues_changes_hash_only_for_depositor(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hashNew, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        _test_setL1BlockValues_changes_hash_only_for_depositor(_number, _timestamp, _basefee, _hashNew, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }

    receive() external payable {}

    fallback() external payable {}
}
